"""Level Factory 0.265.1: an event never moves another anchor's id -- `markers_to_anchors` indexes every other
record first, among themselves, and the gameplay events after; 0.265.0 counted the alarms in the index and moved six
of the Bank Block template's anchor ids with events off. The factory's roadmap 323.

What it changes (anchored; each file pinned by hash; nothing written on a miss): packages/staging/dispatch_inputs.py,
tests/unit/test_gameplay_events.py, VERSION 0.265.0 -> 0.265.1, CHANGELOG.

Generated by `tools/ship_change.py patch` from a proven clone (`_scratch/lf_02651`).

    python patches/patch_lf_event_ids.py
"""
import hashlib
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
REPO = ROOT / 'level_factory'
PINS = {'CHANGELOG.md': '895667bab5dc63f8', 'VERSION': '4d70a7d8a08071e8', 'packages/staging/dispatch_inputs.py': '7ccc322513c4e03d', 'tests/unit/test_gameplay_events.py': 'd93c947a2d758117'}
EDITS = {'CHANGELOG.md': [('lines 1-1', '## [0.265.0] - the gameplay-events switch\n', "## [0.265.1] - an event never moves another anchor's id\n\n0.265.0 said a package with gameplay events off is what it was. Held to that on the Bank Block template -- its\nregistry with events on against the same mission built on 0.264.0 -- the shared anchors' contents matched and six\nanchors' IDS did not: `lot:01_17` became `lot:01_21`, and the same for an objective and both ladders. An id a record\nshares with another is made unique by the record's index in the marker list, and 0.265.0 counted Deli Counter\n0.289.0's alarm markers in that index whether or not it staged them -- with events OFF too. A shell id is the identity\na game maps to its own entity across rebuilds.\n\n### Fixed\n- **`markers_to_anchors` indexes in two passes**: every other record first, among themselves -- exactly the index it\n  had before alarms existed -- and the events after, with their own. Every existing anchor keeps its id whether the\n  alarms are absent, staged off or staged on.\n\n### Tests\n- `tests/unit/test_gameplay_events.py`: an event never moves another anchor's id (fails on 0.265.0).\n\n## [0.265.0] - the gameplay-events switch\n")], 'VERSION': [('lines 1-1', '0.265.0', '0.265.1')], 'packages/staging/dispatch_inputs.py': [('lines 76-76', '    for i, (rec, ftype) in enumerate(_iter_records(gameplay)):\n', '    # TWO PASSES, so an event never moves another anchor\'s id (0.265.1). An id a record shares is made unique by the\n    # record\'s index, and 0.265.0 counted the event markers in that index whether they were staged or not: on the\n    # Bank Block template, six existing anchors\' ids moved (`lot:01_17` -> `lot:01_21`) with events OFF. A shell id is\n    # the identity a game maps to its own entity across rebuilds. Every other record is indexed as it always was, among\n    # themselves, first; the events follow with their own index.\n    records = list(_iter_records(gameplay))\n    plain = [r for r in records if str(r[0].get("type", r[1]) or r[1]) not in EVENT_MARKERS]\n    evented = [r for r in records if str(r[0].get("type", r[1]) or r[1]) in EVENT_MARKERS] if events else []\n    for i, (rec, ftype) in list(enumerate(plain)) + [(len(plain) + j, r) for j, r in enumerate(evented)]:\n'), ('lines 78-79', '        if raw_type in EVENT_MARKERS and not events:\n            continue\n', '')], 'tests/unit/test_gameplay_events.py': [('lines 50-50', '        assert c["type"] == "boolean" and c["default"] is False and c["support"] == "supported"\n', '        assert c["type"] == "boolean" and c["default"] is False and c["support"] == "supported"\n\n\ndef test_an_event_never_moves_another_anchors_id():\n    """0.265.1: ids an existing anchor shares are suffixed by its index, and 0.265.0 counted the alarms in it -- six of\n    the Bank Block template\'s anchors changed id with events OFF. Two buildings\' markers sharing ids, an alarm between:\n    every other anchor\'s id is the same with the alarm absent, events off, and events on."""\n    def site(with_alarm):\n        ms = [{"type": "objective", "id": "A", "x": 0, "y": 0, "z": 0, "building": "b0"}]\n        if with_alarm:\n            ms.append({"type": "alarm", "id": "teller", "x": 1, "y": 0, "z": 0, "building": "b0",\n                       "meta": {"event": "alarm.panic_button", "audible": False}})\n        ms.append({"type": "objective", "id": "A", "x": 5, "y": 0, "z": 0, "building": "b1"})\n        return {"markers": ms}\n    before = [a["id"] for a in markers_to_anchors(site(False), "lot")]\n    off = [a["id"] for a in markers_to_anchors(site(True), "lot")]\n    on = [a["id"] for a in markers_to_anchors(site(True), "lot", events=True) if a["type"] != "trigger"]\n    assert before == off == on, (before, off, on)\n')]}
WHOLE = {}
NEW_FILES = {}


def _sha(text):
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: %s/%s has mixed line endings; nothing written" % (REPO.name, name))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text) != PINS[name]:
        raise SystemExit("REFUSED: %s/%s is %s, not the %s this patch was written against; nothing written"
                         % (REPO.name, name, _sha(text), PINS[name]))
    return text, crlf > 0


def main():
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: %s/%s: the anchor at %s is there %d times; nothing written"
                                 % (REPO.name, name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name, text in WHOLE.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: %s/%s exists already; nothing written" % (REPO.name, name))
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).parent.mkdir(parents=True, exist_ok=True)
        (REPO / name).write_bytes(text.encode("utf-8"))
    print("%s: %d files edited, %d written" % (REPO.name, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
